INSERT INTO domains (id, name, description, display_order, active, version) VALUES
 ('10000000-0000-0000-0000-000000000001', 'Datastrategie', 'Richting, doelen en waarde van data voor de organisatie.', 1, TRUE, 0),
 ('10000000-0000-0000-0000-000000000002', 'Datakwaliteit', 'Meten, bewaken en verbeteren van de kwaliteit van data.', 2, TRUE, 0),
 ('10000000-0000-0000-0000-000000000003', 'Governance', 'Eigenaarschap, beleid en verantwoordelijkheden rond data.', 3, TRUE, 0),
 ('10000000-0000-0000-0000-000000000004', 'Technologie', 'Platformen, architectuur en technische ondersteuning voor data.', 4, TRUE, 0),
 ('10000000-0000-0000-0000-000000000005', 'Processen', 'Herhaalbare en beheerste dataprocessen in de organisatie.', 5, TRUE, 0),
 ('10000000-0000-0000-0000-000000000006', 'Vaardigheden', 'Datageletterdheid en specialistische competenties.', 6, TRUE, 0),
 ('10000000-0000-0000-0000-000000000007', 'Datagedreven besluitvorming', 'Gebruik van data in operationele en strategische besluiten.', 7, TRUE, 0);
INSERT INTO questions (id, domain_id, title, text, explanation, display_order, active, version) VALUES
 ('20000000-0000-0000-0000-000000000011', '10000000-0000-0000-0000-000000000001', 'Strategische verankering', 'In hoeverre is de datastrategie vastgelegd en verbonden met de organisatiedoelen?', 'Kijk naar een vastgestelde visie op data, de koppeling met organisatiedoelen en wie de strategie draagt.', 1, TRUE, 0),
 ('20000000-0000-0000-0000-000000000012', '10000000-0000-0000-0000-000000000001', 'Waardebepaling van data', 'In hoeverre wordt de waarde van datatoepassingen vooraf bepaald en achteraf getoetst?', 'Denk aan businesscases, meetbare doelen voor datainitiatieven en evaluaties van gerealiseerde waarde.', 2, TRUE, 0),
 ('20000000-0000-0000-0000-000000000013', '10000000-0000-0000-0000-000000000001', 'Sturing op het dataportfolio', 'In hoeverre worden datainitiatieven organisatiebreed geprioriteerd en bijgestuurd?', 'Beoordeel of er een overzicht van initiatieven is, wie prioriteert en hoe vaak keuzes worden herzien.', 3, TRUE, 0),
 ('20000000-0000-0000-0000-000000000021', '10000000-0000-0000-0000-000000000002', 'Kwaliteitseisen', 'In hoeverre zijn kwaliteitseisen voor kritieke gegevens vastgelegd?', 'Denk aan afspraken over volledigheid, juistheid, actualiteit en consistentie per gegevensset.', 1, TRUE, 0),
 ('20000000-0000-0000-0000-000000000022', '10000000-0000-0000-0000-000000000002', 'Meten en monitoren', 'In hoeverre wordt datakwaliteit structureel gemeten en zichtbaar gemaakt?', 'Kijk naar kwaliteitsmetingen, dashboards, signalering en de frequentie waarmee wordt gemeten.', 2, TRUE, 0),
 ('20000000-0000-0000-0000-000000000023', '10000000-0000-0000-0000-000000000002', 'Verbeteren bij de bron', 'In hoeverre worden kwaliteitsproblemen bij de bron opgelost en voorkomen?', 'Beoordeel of oorzaken worden geanalyseerd, wie verbeteracties uitvoert en of herhaling wordt voorkomen.', 3, TRUE, 0),
 ('20000000-0000-0000-0000-000000000031', '10000000-0000-0000-0000-000000000003', 'Eigenaarschap', 'In hoeverre zijn eigenaarschap en rentmeesterschap voor kritieke data belegd?', 'Denk aan data-eigenaren, data stewards en de mate waarin zij hun rol daadwerkelijk invullen.', 1, TRUE, 0),
 ('20000000-0000-0000-0000-000000000032', '10000000-0000-0000-0000-000000000003', 'Beleid en afspraken', 'In hoeverre zijn databeleid en -afspraken vastgelegd, bekend en nageleefd?', 'Kijk naar beleid voor gebruik, toegang, bewaring en privacy en hoe naleving wordt getoetst.', 2, TRUE, 0),
 ('20000000-0000-0000-0000-000000000033', '10000000-0000-0000-0000-000000000003', 'Overleg en besluitvorming', 'In hoeverre is er een werkend overlegorgaan dat besluiten neemt over data?', 'Beoordeel of er een datagovernance-overleg is met mandaat, vaste agenda en opvolging van besluiten.', 3, TRUE, 0),
 ('20000000-0000-0000-0000-000000000041', '10000000-0000-0000-0000-000000000004', 'Data-architectuur', 'In hoeverre is er een beschreven en gevolgde data-architectuur?', 'Denk aan een actueel architectuurbeeld, standaarden en keuzes voor opslag, integratie en ontsluiting.', 1, TRUE, 0),
 ('20000000-0000-0000-0000-000000000042', '10000000-0000-0000-0000-000000000004', 'Integratie en ontsluiting', 'In hoeverre kunnen gegevens betrouwbaar en herbruikbaar worden uitgewisseld?', 'Kijk naar koppelingen, API''s, een centraal dataplatform en het voorkomen van dubbele opslag.', 2, TRUE, 0),
 ('20000000-0000-0000-0000-000000000043', '10000000-0000-0000-0000-000000000004', 'Beveiliging en continuïteit', 'In hoeverre zijn beveiliging, toegang en continuïteit van dataplatformen geregeld?', 'Beoordeel toegangsbeheer, logging, back-ups en het testen van herstelprocedures.', 3, TRUE, 0),
 ('20000000-0000-0000-0000-000000000051', '10000000-0000-0000-0000-000000000005', 'Beschreven processen', 'In hoeverre zijn de belangrijkste dataprocessen beschreven?', 'Denk aan processen voor het vastleggen, verwerken, beheren en verwijderen van gegevens.', 1, TRUE, 0),
 ('20000000-0000-0000-0000-000000000052', '10000000-0000-0000-0000-000000000005', 'Beheersing en verbetering', 'In hoeverre worden dataprocessen gemeten, beheerst en verbeterd?', 'Kijk naar procesindicatoren, periodieke evaluaties en een vaste verbetercyclus.', 2, TRUE, 0),
 ('20000000-0000-0000-0000-000000000053', '10000000-0000-0000-0000-000000000005', 'Levenscyclus van data', 'In hoeverre wordt de volledige levenscyclus van data bewust beheerd?', 'Beoordeel afspraken over archivering, bewaartermijnen en het tijdig verwijderen van gegevens.', 3, TRUE, 0),
 ('20000000-0000-0000-0000-000000000061', '10000000-0000-0000-0000-000000000006', 'Datageletterdheid', 'In hoeverre kunnen medewerkers data begrijpen, interpreteren en kritisch gebruiken?', 'Denk aan basiskennis van data bij medewerkers en leidinggevenden en het gebruik daarvan in het werk.', 1, TRUE, 0),
 ('20000000-0000-0000-0000-000000000062', '10000000-0000-0000-0000-000000000006', 'Specialistische kennis', 'In hoeverre beschikt de organisatie over de benodigde specialistische datakennis?', 'Kijk naar rollen zoals data-engineer, analist en data scientist en de afhankelijkheid van externen.', 2, TRUE, 0),
 ('20000000-0000-0000-0000-000000000063', '10000000-0000-0000-0000-000000000006', 'Ontwikkeling en leren', 'In hoeverre worden datavaardigheden gericht en structureel ontwikkeld?', 'Beoordeel opleidingsplannen, leertrajecten en het delen van kennis binnen de organisatie.', 3, TRUE, 0),
 ('20000000-0000-0000-0000-000000000071', '10000000-0000-0000-0000-000000000007', 'Gebruik in besluiten', 'In hoeverre worden besluiten aantoonbaar onderbouwd met data?', 'Denk aan het gebruik van rapportages en analyses in management- en bestuursoverleg.', 1, TRUE, 0),
 ('20000000-0000-0000-0000-000000000072', '10000000-0000-0000-0000-000000000007', 'Informatievoorziening', 'In hoeverre is betrouwbare stuurinformatie tijdig en eenduidig beschikbaar?', 'Kijk naar eenduidige definities, actuele dashboards en één versie van de waarheid.', 2, TRUE, 0),
 ('20000000-0000-0000-0000-000000000073', '10000000-0000-0000-0000-000000000007', 'Experimenteren en leren', 'In hoeverre toetst de organisatie aannames met data en leert zij van de uitkomsten?', 'Beoordeel het gebruik van experimenten, evaluaties achteraf en het bijstellen van beleid op basis van data.', 3, TRUE, 0);
